package com.witchersbestiary.test;
import com.witchersbestiary.board.*;
import com.witchersbestiary.contracts.*;
import com.witchersbestiary.contracts.hunt.*;
import com.witchersbestiary.contracts.procedural.*;
import com.witchersbestiary.contracts.tracking.*;
import com.witchersbestiary.client.tracking.WitcherSensesClient;
import net.fabricmc.api.ClientModInitializer;
import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;
import net.minecraft.client.MinecraftClient;
import net.minecraft.client.option.KeyBinding;
import net.minecraft.client.util.*;
import net.minecraft.client.gui.screen.TitleScreen;
import net.minecraft.block.Blocks;
import net.minecraft.entity.*;
import net.minecraft.entity.mob.MobEntity;
import net.minecraft.item.*;
import net.minecraft.registry.*;
import net.minecraft.resource.DataConfiguration;
import net.minecraft.util.*;
import net.minecraft.util.hit.BlockHitResult;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraft.world.gen.*;
import net.minecraft.world.level.LevelInfo;
import java.nio.file.*;
import java.util.*;
/** Real input/packets and rendering in one bounded native client, two full investigations. */
public final class InvestigationReviewClient implements ClientModInitializer {
 private static final Path OUT=Path.of("../stage20d-review");
 private int phase,ticks,index,button,progress,total,expectedReward;private boolean rejoined;private volatile boolean ready,finished;private volatile Throwable failure;private String folder,routeSnapshot;private BlockPos root;private volatile UUID contract,target,next;private final Map<String,Object> results=new LinkedHashMap<>();
 private Identifier id(){return index==0?ProceduralHunts.id("foglet"):GraveDevourer.ID;}
 private String name(){return index==0?"procedural":"legendary";}
 private void record(String key,Object value){results.put(name()+"."+key,value);}
 public void onInitializeClient(){try{Files.createDirectories(OUT);for(String name:new String[]{"failure.txt","timeout.txt","results.json"})if(Files.exists(OUT.resolve(name)))Files.move(OUT.resolve(name),OUT.resolve(System.currentTimeMillis()+"-"+name));}catch(Exception e){throw new RuntimeException(e);}ClientTickEvents.END_CLIENT_TICK.register(this::tick);var watchdog=new Thread(()->{try{Thread.sleep(420000);if(!finished){Files.writeString(OUT.resolve("timeout.txt"),"420s investigation native limit");Runtime.getRuntime().halt(2);}}catch(Exception ignored){}},"investigation-review-limit");watchdog.setDaemon(true);watchdog.start();}
 private void server(MinecraftClient c,Runnable action){ready=false;c.getServer().execute(()->{try{action.run();ready=true;}catch(Throwable t){failure=t;}});}
 private void capture(MinecraftClient c,String file)throws Exception{try(var image=ScreenshotRecorder.takeScreenshot(c.getFramebuffer())){image.writeTo(OUT.resolve(name()+"-"+file+".png"));}}
 private void open(MinecraftClient c){server(c,()->{var w=c.getServer().getOverworld();var p=c.getServer().getPlayerManager().getPlayerList().getFirst();p.changeGameMode(GameMode.CREATIVE);p.teleport(w,.5,root.getY(),-2,0,0);w.getBlockState(root).onUse(w,p,new BlockHitResult(root.toCenterPos(),Direction.NORTH,root,false));});}
 private void select(MinecraftClient c)throws Exception{var h=(BoardScreenHandler)c.player.currentScreenHandler;var offers=h.snapshot.getAsJsonArray("offers");if(offers==null)return;for(int n=0;n<offers.size();n++)if(offers.get(n).getAsJsonObject().get("id").getAsString().equals(id().toString())){button=offers.get(n).getAsJsonObject().get("button").getAsInt();for(String fieldName:new String[]{"selected","page"}){var field=c.currentScreen.getClass().getDeclaredField(fieldName);field.setAccessible(true);field.setInt(c.currentScreen,fieldName.equals("selected")?n:n/3);}((com.witchersbestiary.client.board.NoticeBoardScreen)c.currentScreen).refresh();}}
 private void approach(MinecraftClient c){var p=c.getServer().getPlayerManager().getPlayerList().getFirst();var instance=ContractState.get(c.getServer()).find(contract);var clue=instance.investigation.next();if(clue==null)throw new IllegalStateException("Missing next clue");next=clue.id;progress=instance.investigation.current;total=instance.investigation.clues.size();p.setNoGravity(true);p.teleport(p.getServerWorld(),clue.position.getX()+.5,clue.position.getY(),clue.position.getZ()-2,0,40);}
 private void battle(MinecraftClient c){var p=c.getServer().getPlayerManager().getPlayerList().getFirst();var instance=ContractState.get(c.getServer()).find(contract);if(instance.hunt.target==null||instance.investigation.stage!=ContractInvestigation.Stage.HUNTING)throw new IllegalStateException("No encounter after final clue");target=instance.hunt.target;var boss=(MobEntity)p.getServerWorld().getEntity(target);if(boss==null)throw new IllegalStateException("Target entity missing");expectedReward+=instance.definition().reward().items().getFirst().count();record("all_clues_studied",instance.investigation.current);record("deferred_unique_spawn",true);p.changeGameMode(GameMode.SURVIVAL);p.setInvulnerable(false);p.setHealth(20);p.equipStack(EquipmentSlot.HEAD,new ItemStack(Items.NETHERITE_HELMET));p.equipStack(EquipmentSlot.CHEST,new ItemStack(Items.NETHERITE_CHESTPLATE));p.equipStack(EquipmentSlot.LEGS,new ItemStack(Items.NETHERITE_LEGGINGS));p.equipStack(EquipmentSlot.FEET,new ItemStack(Items.NETHERITE_BOOTS));p.addStatusEffect(new net.minecraft.entity.effect.StatusEffectInstance(net.minecraft.entity.effect.StatusEffects.REGENERATION,1800,4));p.setStackInHand(Hand.MAIN_HAND,new ItemStack(Items.NETHERITE_SWORD));p.teleport(p.getServerWorld(),boss.getX(),boss.getY(),boss.getZ()-5,0,0);boss.setTarget(p);}
 private void tick(MinecraftClient c){try{
  if(failure!=null)throw new IllegalStateException(failure);
  if(phase==0){if(c.getOverlay()!=null)return;c.options.pauseOnLostFocus=false;c.options.getViewDistance().setValue(5);c.options.getSimulationDistance().setValue(5);c.options.getGuiScale().setValue(2);c.options.getFov().setValue(70);folder="Investigation-"+System.currentTimeMillis();phase=1;c.createIntegratedServerLoader().createAndStart(folder,new LevelInfo("Investigation Review",GameMode.CREATIVE,false,Difficulty.NORMAL,true,new GameRules(),DataConfiguration.SAFE_MODE),new GeneratorOptions(202001L,false,false),r->r.get(RegistryKeys.WORLD_PRESET).get(WorldPresets.FLAT).createDimensionsRegistryHolder(),null);return;}
  if(phase==1&&c.player!=null){c.setScreen(null);if(++ticks<80)return;phase=2;ticks=0;server(c,()->{var w=c.getServer().getOverworld();int y=w.getTopY(Heightmap.Type.WORLD_SURFACE,0,0);root=new BlockPos(0,y,0);w.getGameRules().get(GameRules.DO_MOB_SPAWNING).set(false,c.getServer());w.setTimeOfDay(6000);for(var mob:w.getEntitiesByClass(MobEntity.class,new Box(-128,y-10,-128,128,y+30,128),e->true))mob.discard();var forest=w.getRegistryManager().get(RegistryKeys.BIOME).getEntry(net.minecraft.world.biome.BiomeKeys.FOREST).orElseThrow();for(int x=-6;x<=6;x++)for(int z=-6;z<=6;z++){var chunk=w.getChunkManager().getWorldChunk(x,z);if(chunk!=null){chunk.populateBiomes((a,b,d,s)->forest,w.getChunkManager().getNoiseConfig().getMultiNoiseSampler());chunk.setNeedsSaving(true);}}if(!NoticeBoardBlock.place(w,root,Direction.NORTH))throw new IllegalStateException("Board placement");});return;}
  if(phase==2&&ready){phase=3;open(c);return;}
  if(phase==3&&ready&&c.currentScreen instanceof com.witchersbestiary.client.board.NoticeBoardScreen){select(c);if(++ticks==20)capture(c,"available");if(ticks==25)c.interactionManager.clickButton(c.player.currentScreenHandler.syncId,button);if(ticks==65){capture(c,"tracking-journal");c.player.closeHandledScreen();phase=10;ticks=0;server(c,()->{var instance=BoardScreenHandler.existing(c.getServer().getPlayerManager().getPlayerList().getFirst(),id());if(instance==null||instance.investigation.stage!=ContractInvestigation.Stage.TRACKING||instance.hunt.target!=null)throw new IllegalStateException("Investigation not prepared before target");contract=instance.id();record("no_early_target",true);record("clue_total",instance.investigation.clues.size());approach(c);});}return;}
  if(phase==10&&ready){ticks++;if(!WitcherSensesClient.enabled()&&ticks%20==1)KeyBinding.onKeyPressed(InputUtil.fromKeyCode(org.lwjgl.glfw.GLFW.GLFW_KEY_V,0));var snapshot=WitcherSensesClient.snapshot();if(!WitcherSensesClient.enabled()||!snapshot.has("point")||!snapshot.getAsJsonObject("point").has("id")||!snapshot.getAsJsonObject("point").get("id").getAsString().equals(next.toString())){if(ticks>120)throw new IllegalStateException("Private visible clue missing "+snapshot);return;}record("real_v_toggle",true);var point=snapshot.getAsJsonObject("point");var destination=new Vec3d(point.get("x").getAsDouble()+.5,point.get("y").getAsDouble()+.06,point.get("z").getAsDouble()+.5);var delta=destination.subtract(c.player.getEyePos());c.player.setYaw((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)));c.player.setPitch((float)-Math.toDegrees(Math.atan2(delta.y,Math.sqrt(delta.horizontalLengthSquared()))));if(ticks>=16){capture(c,"clue-"+progress);c.interactionManager.interactItem(c.player,Hand.MAIN_HAND);phase=11;ticks=0;}return;}
  if(phase==11&&ready&&++ticks==12){server(c,()->{var instance=ContractState.get(c.getServer()).find(contract);if(instance.investigation.current!=progress+1)throw new IllegalStateException("Real right-click study failed");record("right_click_progress",instance.investigation.current);if(instance.investigation.stage==ContractInvestigation.Stage.HUNTING){phase=4;ticks=0;battle(c);}else if(instance.investigation.stage==ContractInvestigation.Stage.LAIR_FOUND){phase=13;ticks=0;}else if(index==0&&!rejoined&&instance.investigation.current==1){routeSnapshot=instance.investigation.write().toString();phase=12;ticks=0;}else{approach(c);phase=10;ticks=0;}});return;}
  if(phase==13&&ready&&++ticks==20){server(c,()->{var instance=ContractState.get(c.getServer()).find(contract);var p=c.getServer().getPlayerManager().getPlayerList().getFirst();Investigations.trySpawn(p,instance);if(instance.hunt.target==null)throw new IllegalStateException("Pending lair, biome="+p.getServerWorld().getBiome(instance.investigation.lair)+" safe="+GraveDevourer.safe(p.getServerWorld(),instance.investigation.lair,true));phase=4;ticks=0;battle(c);});return;}
  if(phase==12&&ready){phase=8;ticks=0;c.world.disconnect();c.disconnect();c.setScreen(new TitleScreen());return;}
  if(phase==8){if(c.world==null&&c.getServer()==null&&++ticks>20){phase=9;ticks=0;c.createIntegratedServerLoader().start(folder,()->{failure=new IllegalStateException("Rejoin cancelled");});}return;}
  if(phase==9&&c.player!=null&&++ticks>80){phase=10;ticks=0;rejoined=true;server(c,()->{var instance=ContractState.get(c.getServer()).find(contract);if(instance.hunt.target!=null||!instance.investigation.write().toString().equals(routeSnapshot))throw new IllegalStateException("Route/progress changed on real rejoin");if(!c.getServer().getOverworld().getBiome(instance.investigation.lair).isIn(net.minecraft.registry.tag.BiomeTags.IS_FOREST))throw new IllegalStateException("Native forest biome fixture did not persist");record("tracking_world_rejoin",true);approach(c);});return;}
  if(phase==4&&ready){if(++ticks==20)capture(c,"lair-and-boss");if(ticks==35){phase=5;ticks=0;server(c,()->{var p=c.getServer().getPlayerManager().getPlayerList().getFirst();var boss=(MobEntity)p.getServerWorld().getEntity(target);p.teleport(p.getServerWorld(),boss.getX(),boss.getY(),boss.getZ()-2,0,0);record("boss_bars",SwampLord.bossBars());});}return;}
  if(phase==5&&ready){ticks++;Entity boss=null;for(var e:c.world.getEntities())if(e.getUuid().equals(target))boss=e;if(boss!=null&&boss.isAlive()&&ticks%25==0){c.interactionManager.attackEntity(c.player,boss);c.player.swingHand(Hand.MAIN_HAND);}if(ticks%20==0)c.getServer().execute(()->{var p=c.getServer().getPlayerManager().getPlayerList().getFirst();var e=p.getServerWorld().getEntity(target);if(e!=null&&p.squaredDistanceTo(e)>9)p.teleport(p.getServerWorld(),e.getX(),e.getY(),e.getZ()-2,0,0);});if(ticks==70)capture(c,"combat");if(ticks>600)throw new IllegalStateException("Combat timeout");if(ticks>30&&(boss==null||!boss.isAlive())){phase=6;ticks=0;server(c,()->{var instance=ContractState.get(c.getServer()).find(contract);if(instance.status()!=ContractInstance.Status.COMPLETED||instance.investigation.stage!=ContractInvestigation.Stage.COMPLETED)throw new IllegalStateException("Investigation/contract completion missing");record("completed",true);record("bars_after_death",SwampLord.bossBars());});}return;}
  if(phase==6&&ready){phase=7;open(c);return;}
  if(phase==7&&ready&&c.currentScreen instanceof com.witchersbestiary.client.board.NoticeBoardScreen){select(c);if(++ticks==20)capture(c,"completed-journal");if(ticks==25)c.interactionManager.clickButton(c.player.currentScreenHandler.syncId,button+32);if(ticks==50){capture(c,"rewarded");server(c,()->{var p=c.getServer().getPlayerManager().getPlayerList().getFirst();if(ContractState.get(c.getServer()).find(contract).status()!=ContractInstance.Status.REWARDED||p.getInventory().count(Items.EMERALD)!=expectedReward)throw new IllegalStateException("Reward failed");record("claimed",true);});}if(ticks==65){Files.writeString(OUT.resolve("results.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(results));if(++index<2){phase=2;ticks=0;ready=true;return;}finished=true;c.scheduleStop();}return;}
 }catch(Throwable t){try{Files.writeString(OUT.resolve("failure.txt"),t+"\n"+Arrays.toString(t.getStackTrace()));}catch(Exception ignored){}finished=true;c.scheduleStop();}}
}
